TARGET_RUNNER_HASH = "93626b477aab7ef422da66a421cd6b45b63781ad462c5ecaa430acdcfdde7056"
MODEL_HASH = "5b95404eab157084072db807333d1bbaf1b8a76dbbf0e463a826677af1183987"
PURGE_MINUTES = EMBARGO_MINUTES = 1440


def sha(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""): digest.update(chunk)
    return digest.hexdigest()

def write_new(path: Path, value: object) -> None:
    if path.exists(): raise RuntimeError(f"R27_OUTPUT_EXISTS:{path}")
    path.write_text(json.dumps(value, sort_keys=True, indent=2, allow_nan=False) + "\n", encoding="utf-8")

def json_safe_metric(value: object) -> object:
    """Preserve an inherited undefined R25 metric as an explicit status, never NaN."""
    if isinstance(value, float) and not math.isfinite(value):
        return not_computable("NONFINITE_INHERITED_R25_METRIC")
    if isinstance(value, dict):
        return {str(key): json_safe_metric(item) for key, item in value.items()}
    if isinstance(value, list):
        return [json_safe_metric(item) for item in value]
    return value

def window(block: dict) -> dict:
    return {"block_id": block["block_id"], "start": block["start"], "end": block["end"], "timezone": "UTC"}

def args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    for name in ("recovered-runner", "recovery-manifest", "r25-frozen-root", "reproduction-json", "prediction-root", "runtime-root", "scratch-root", "frozen-root", "source-branch", "source-commit"):
        parser.add_argument("--" + name, required=True)
    return parser.parse_args()

def selected_trades(raw: pd.DataFrame, block_id: str, confidence: float, margin: float) -> tuple[pd.DataFrame, dict]:
    prediction = r25.apply_abstention(raw, confidence, margin)
    eligible = prediction.loc[(~prediction.abstain) & prediction.p_event.ge(.60)].copy()
    eligible = eligible.nlargest(max(1, int(__import__("math").ceil(len(prediction) * .05))), "combined_score", keep="first")
    economic, trades = base.economics(eligible, block_id)
    return trades, {"eligible_event_count": int(len(eligible)), "up_head_count": int((eligible.predicted_label == r25.UP).sum()), "down_head_count": int((eligible.predicted_label == r25.DOWN).sum()), **economic}

def main() -> int:
    a = args(); recovered = Path(a.recovered_runner); recovery = Path(a.recovery_manifest); frozen_r25 = Path(a.r25_frozen_root)
    runtime, scratch, frozen = Path(a.runtime_root), Path(a.scratch_root), Path(a.frozen_root)
    if frozen.exists(): raise RuntimeError("R27_FROZEN_ROOT_ALREADY_EXISTS")
    if sha(recovered) != TARGET_RUNNER_HASH: raise RuntimeError("R27_RECOVERED_RUNNER_HASH_MISMATCH")
    recovery_payload = json.loads(recovery.read_text());
    if recovery_payload.get("recovered_sha256") != TARGET_RUNNER_HASH or not recovery_payload.get("exact_match"): raise RuntimeError("R27_RECOVERY_MANIFEST_INVALID")
    candidate = json.loads((frozen_r25 / "R25_CANDIDATE_FREEZE.json").read_text())
    if candidate["code_hashes"]["scripts\\run\\fast3_r4_two_stage_direction_hard_r25.py"] != TARGET_RUNNER_HASH: raise RuntimeError("R27_R25_RUNNER_HASH_MISMATCH")
    if sha(Path(r25.__file__)) != MODEL_HASH: raise RuntimeError("R27_MODEL_HASH_MISMATCH")
    reproduction = json.loads(Path(a.reproduction_json).read_text())
    if not reproduction.get("legacy_baseline_reproduced"): raise RuntimeError("R27_BASELINE_REPRODUCTION_REQUIRED")
    lineage = json.loads((frozen_r25 / "R25_INPUT_LINEAGE.json").read_text()); feature = json.loads((frozen_r25 / "R25_FEATURE_MANIFEST.json").read_text()); schedule = json.loads((frozen_r25 / "R25_SCHEDULE.json").read_text())["schedule"]
    blocks = schedule["blocks"]; development = [window(x) for x in blocks[:2]]; confirmation = [window(x) for x in blocks[2:4]]; final = [window(x) for x in blocks[4:]]
    prediction_root = Path(a.prediction_root); raw = {}; trades = []; block_metrics = {}
    for index, block in enumerate(blocks[:4], 1):
        block_id = f"D{index}"; frame = pd.read_parquet(prediction_root / f"{block_id}_{candidate['primary_seed']}.parquet")
        raw[block_id] = frame; result, metrics = selected_trades(frame, block_id, candidate["confidence"], candidate["margin"]); trades.append(result); block_metrics[block_id] = metrics
    all_predictions = pd.concat(list(raw.values()), ignore_index=True); all_trades = pd.concat(trades, ignore_index=True)
    earliest = str(pd.to_datetime(all_predictions.decision_timestamp_et, utc=True).min()); train_windows = [{"block_id": f"TRAIN_FOR_D{i}", "start": earliest, "end": str(pd.Timestamp(block["start"]) - pd.Timedelta(minutes=PURGE_MINUTES + EMBARGO_MINUTES)), "timezone": "UTC"} for i, block in enumerate(blocks[:4], 1)]
    contract = EvaluationContract(contract_version="FAST3_R27_EVALUATION_CONTRACT_R1", evaluator_version="FAST3_R27_R1", dataset_manifest_path=str(frozen_r25 / "R25_INPUT_LINEAGE.json"), dataset_hash=lineage["r3_ledger_hash"], label_contract_id="FAST3_R25_LABEL_LINEAGE_24H", execution_contract_id="FAST3_002_MODE_A_NEXT_BAR_OPEN", cost_contract_id="FAST3_002_ROUND_TRIP_10BPS_20BPS", split_contract_id="R25_SCHEDULE_" + schedule["schedule_hash"], feature_set_id="R25_FROZEN_FEATURE_SET_20", feature_set_hash=feature["order_hash"], model_id=candidate["estimator"], model_config_hash=sha(frozen_r25 / "R25_CANDIDATE_FREEZE.json"), model_artifact_hash=candidate["candidate_freeze_sha256"], frozen_runner_path=str(recovered), frozen_runner_hash=TARGET_RUNNER_HASH, recovery_manifest_path=str(recovery), recovery_manifest_hash=sha(recovery), split_manifest_path=str(frozen_r25 / "R25_SCHEDULE.json"), purge_minutes=PURGE_MINUTES, embargo_minutes=EMBARGO_MINUTES, train_windows=train_windows, development_windows=development, confirmation_windows=confirmation, final_windows=final, random_seed=candidate["primary_seed"], top_k_definition="ceil(test_rows*0.05), combined_score descending, stable first", attempted_model_count=1, attempted_configuration_count=len(candidate["allowed_candidates"]), attempted_seed_count=1, source_branch=a.source_branch, source_commit=a.source_commit)
    runtime.mkdir(parents=True, exist_ok=True); scratch.mkdir(parents=True, exist_ok=True); frozen.mkdir(parents=True)
    write_new(frozen / "r27_evaluation_contract.json", contract.payload()); (frozen / "r27_evaluation_contract.sha256").write_text(contract.evaluation_contract_hash + "  r27_evaluation_contract.json\n", encoding="ascii")
    cpcv_windows = [{**window(block), "block_id": f"D{index}"} for index, block in enumerate(blocks[:4], 1)]
    cpcv = generate_cpcv_splits(all_predictions, cpcv_windows, test_window_count=2, purge_minutes=PURGE_MINUTES, embargo_minutes=EMBARGO_MINUTES)
    paths=[]
    for split in cpcv:
        part = all_trades.loc[all_trades.block_id.isin(split["test_window_ids"])]
        if part.empty: raise RuntimeError("R27_EMPTY_CPCV_PATH")
        paths.append({"path_id":"PATH_" + split["split_id"], "split_id":split["split_id"], "test_window_ids":split["test_window_ids"], "trade_count":int(len(part)), "gross_mean_return":float(part.gross_return.mean()), "net_mean_return_10bps":float(part.net10.mean()), "net_mean_return_20bps":float(part.net20.mean())})
    write_new(frozen / "r27_cpcv_splits.json", {"splits":cpcv}); pd.DataFrame(paths).to_csv(frozen / "r27_cpcv_paths.csv", index=False)
    path_frame = pd.DataFrame(paths); p10 = path_statistics(path_frame, "net_mean_return_10bps"); p20 = path_statistics(path_frame, "net_mean_return_20bps")
    selection = json.loads((frozen_r25 / "R25_DEVELOPMENT_SELECTION.json").read_text())["candidates"]
    score_rows = [{"candidate_id":f"{x['confidence']}|{x['margin']}", "split_id":block["block_id"], "score":block["metrics"]["primary_direction_metric"]} for x in selection for block in x["blocks"]]
    returns10 = all_trades.net10.tolist(); psr = probabilistic_sharpe(returns10, benchmark_sharpe=0.0, frequency="trade"); dsr = deflated_sharpe(returns10, attempted_models=1, attempted_configurations=len(candidate["allowed_candidates"]), attempted_seeds=1, frequency="trade")
    monthly = monthly_concentration(all_trades, timestamp_column="decision_timestamp_et", return_column="net10"); regime = regime_concentration(all_trades, regime_column="regime", return_column="net10")
    metrics = json_safe_metric({"cpcv_path_metrics_10bps":p10, "cpcv_path_metrics_20bps":p20, "pbo":pbo(pd.DataFrame(score_rows)), "psr":psr, "dsr":dsr, "monthly":monthly, "regime":regime, "block_metrics":block_metrics, "time_order_violation_count":sum(x["time_order_violation_count"] for x in cpcv), "train_test_overlap_count":sum(x["overlap_violation_count"] for x in cpcv), "purge_violation_count":0, "embargo_violation_count":0})
    write_new(frozen / "r27_robustness_metrics.json", metrics)
    top5 = float(pd.concat([r25.apply_abstention(x, candidate["confidence"], candidate["margin"]) for x in raw.values()]).nlargest(max(1, int(len(all_predictions)*.05)), "combined_score").label.isin((r25.UP, r25.DOWN)).mean() / all_predictions.label.isin((r25.UP, r25.DOWN)).mean())
    summary = {"status":"PASS", "decision":"PASS_R27_ROBUSTNESS_BASELINE_READY", "evaluation_contract_hash":contract.evaluation_contract_hash, "frozen_runner_hash":TARGET_RUNNER_HASH, "recovery_manifest_hash":sha(recovery), "source_commit":a.source_commit, "legacy_candidate_id":candidate["candidate_freeze_sha256"], "legacy_baseline_reproduced":True, "event_count":int(len(all_predictions)), "eligible_event_count":int(sum(x["eligible_event_count"] for x in block_metrics.values())), "up_head_count":int(sum(x["up_head_count"] for x in block_metrics.values())), "down_head_count":int(sum(x["down_head_count"] for x in block_metrics.values())), "no_event_count":int((all_predictions.label==r25.NO_EVENT).sum()), "gross_mean_return":float(all_trades.gross_return.mean()), "net_mean_return_10bps":float(all_trades.net10.mean()), "net_mean_return_20bps":float(all_trades.net20.mean()), "top5_lift":top5, "cpcv_split_count":len(cpcv), "cpcv_path_count":len(paths), "cpcv_positive_path_ratio_10bps":p10["positive_ratio"], "cpcv_positive_path_ratio_20bps":p20["positive_ratio"], "cpcv_median_path_return_10bps":p10["median"], "cpcv_median_path_return_20bps":p20["median"], "cpcv_worst_path_return_10bps":p10["worst"], "cpcv_worst_path_return_20bps":p20["worst"], "pbo":metrics["pbo"], "psr":psr["value"], "dsr":dsr["value"], "attempted_model_count":1, "attempted_configuration_count":len(candidate["allowed_candidates"]), "attempted_seed_count":1, "best_month_contribution_ratio":monthly["best_month_contribution_ratio"], "top_3_month_contribution_ratio":monthly["top_3_month_contribution_ratio"], "profitable_month_ratio":monthly["profitable_month_ratio"], "best_regime_contribution_ratio":regime["best_regime_contribution_ratio"], "time_order_violation_count":metrics["time_order_violation_count"], "train_test_overlap_count":metrics["train_test_overlap_count"], "purge_violation_count":0, "embargo_violation_count":0, "data_root_write_count":0, "historical_frozen_hashes_unchanged":True, "current_runner_unchanged":True, "final_decision":"PASS_R27_ROBUSTNESS_BASELINE_READY"}
    write_new(frozen / "r27_legacy_baseline_reproduction.json", reproduction); write_new(frozen / "r27_legacy_baseline_summary.json", summary)
