    ledger.append({"experiment_id":experiment_id,"parent_experiment_id":candidate["candidate_freeze_sha256"],"created_at_utc":datetime.now(timezone.utc).isoformat().replace("+00:00","Z"),"source_branch":a.source_branch,"source_commit":a.source_commit,"dirty_worktree":False,"evaluator_version":"FAST3_R27_R1","evaluation_contract_hash":contract.evaluation_contract_hash,"dataset_hash":lineage["r3_ledger_hash"],"feature_set_hash":feature["order_hash"],"model_config_hash":sha(frozen_r25 / "R25_CANDIDATE_FREEZE.json"),"model_artifact_hash":candidate["candidate_freeze_sha256"],"frozen_runner_hash":TARGET_RUNNER_HASH,"random_seed":candidate["primary_seed"],"attempted_model_count":1,"attempted_configuration_count":len(candidate["allowed_candidates"]),"attempted_seed_count":1,"train_window":train_windows,"development_window":development,"confirmation_window":confirmation,"final_window":final,"purge_minutes":PURGE_MINUTES,"embargo_minutes":EMBARGO_MINUTES,"cost_bps":[10,20],"gross_metrics":{"mean":summary["gross_mean_return"]},"net_metrics":{"mean_10bps":summary["net_mean_return_10bps"],"mean_20bps":summary["net_mean_return_20bps"]},"robustness_metrics":metrics,"decision":summary["decision"],"rejection_reason":"", "artifact_paths":{}})
    report = "# FAST3 R27 robustness baseline\n\nFrozen R25 runner replay reproduced before this evaluation. Economic returns follow the inherited R25 `base.economics` fallback: its frozen input has no `gross_return`, so gross is zero and net is the immutable 10/20 bps cost deduction.\n"
    (frozen / "FAST3_R27_ROBUSTNESS_BASELINE_R1_REPORT.md").write_text(report, encoding="utf-8")
